// MedPass end-to-end run on a REAL Midnight network with REAL zero-knowledge
// proofs. Deploys the contract, then drives a full lifecycle through the node:
//
//   register_party (x4) -> create_batch -> record_import -> verify -> dispense
//   -> clone attempt -> recall_batch -> post-recall scan -> revoke_party
//
// Every step is a submitted, finalized transaction whose proof was generated by
// the proof server. A deployment record is written to deployments/<network>.json.
//
// Usage: tsx scripts/run-lifecycle.ts [undeployed|preview|preprod]

import * as fs from 'node:fs';
import * as path from 'node:path';
import { createHash } from 'node:crypto';

import { deployContract, findDeployedContract } from '@midnight-ntwrk/midnight-js-contracts';
import { setNetworkId } from '@midnight-ntwrk/midnight-js-network-id';
import { toHex } from '@midnight-ntwrk/midnight-js-utils';

import { resolveNetwork, resolveNetworkConfig } from './shared/network.js';
import { buildWallet, createProviders, ensureDust, projectRoot, type WalletContext } from './shared/wallet.js';
import { createCompiledMedPass, setActive } from './shared/medpass.js';
import { PartyRole, ledger, pureCircuits } from '../src/managed/medpass/contract/index.js';
import { buildUnitTree, participantId, partyLeaf } from '../tests/helpers/simulator.js';

// The local devnet pre-funds this account (midnight-local-dev accounts.json).
const MNEMONIC = process.env.MEDPASS_WALLET_MNEMONIC
  ?? 'abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon art';

const sha = (s: string) => new Uint8Array(createHash('sha256').update(s).digest());

const REGULATOR = sha('medpass:regulator');
const MANUFACTURER = sha('medpass:manufacturer-acme');
const IMPORTER = sha('medpass:importer-globalmed');
const PHARMACY_A = sha('medpass:pharmacy-citycare');
const PHARMACY_B = sha('medpass:pharmacy-ruralhealth');

const BATCH = sha('medpass:batch-2026-001');
const METADATA = sha('medpass:meta-2026-001');
const TERMS = sha('medpass:terms-2026-001');
const EXPIRY = BigInt(Math.floor(Date.now() / 1000) + 365 * 24 * 3600);

const UNIT_CODES = Array.from({ length: 4 }, (_, i) => sha(`medpass:unit-2026-001-${i}`));
const UNIT_TREE = buildUnitTree(UNIT_CODES);

const log = (...a: unknown[]) => console.log(...a);
const rule = () => log('─'.repeat(72));
const firstLine = (e: unknown) => (e instanceof Error ? e.message : String(e)).split('\n')[0];

// Endpoint URLs may carry API credentials in query params (e.g. Blockfrost's
// project_id). Never persist or print those.
const redact = (url: string) =>
  url.replace(/([?&](?:project_id|token|apikey|api_key)=)[^&]*/gi, '$1REDACTED');
const redactedConfig = (c: ReturnType<typeof resolveNetworkConfig>) => ({
  ...c,
  indexer: redact(c.indexer),
  indexerWS: redact(c.indexerWS),
  node: redact(c.node),
  nodeWS: redact(c.nodeWS),
});

function txLine(label: string, r: any) {
  const pub = r?.public ?? {};
  log(`  ${label.padEnd(18)} txId=${pub.txId ?? '(n/a)'}`);
  if (pub.blockHeight !== undefined) log(`  ${''.padEnd(18)} block=${pub.blockHeight}`);
}

async function main() {
  const network = resolveNetwork(process.argv[2]);
  setNetworkId(network);
  const config = resolveNetworkConfig(network);

  log();
  log('MedPass — anti-counterfeit medicine passport');
  log(`Live run against Midnight ${network} with REAL zk proofs`);
  rule();
  log(`indexer:      ${redact(config.indexer)}`);
  log(`node:         ${redact(config.node)}`);
  log(`proof server: ${config.proofServer}`);
  log();

  const walletCtx: WalletContext = await buildWallet(config, MNEMONIC);
  let deployed: any;
  const txids: Record<string, string> = {};

  try {
    log('Syncing wallet and preparing DUST…');
    const dust = await ensureDust(walletCtx);
    log(`Wallet: ${String(walletCtx.unshieldedKeystore.getBech32Address())}`);
    log(`DUST:   ${dust.toString()}`);
    log();

    const providers = await createProviders(walletCtx, config);
    const compiledContract = createCompiledMedPass();

    // Each call must pass the CURRENT registry root and prove membership with a
    // private Merkle path read from the live ledger. This helper reads the
    // on-chain state and derives, for a given party, its (root, path) pair.
    const live = async () => {
      const state = await providers.publicDataProvider.queryContractState(
        deployed.deployTxData.public.contractAddress,
      );
      if (!state) throw new Error('contract state not visible through the indexer yet');
      return ledger(state.data);
    };

    // The indexer can trail the node by a block, so poll until the party's leaf
    // is visible in the freshly-read tree before deriving its membership proof.
    const membership = async (which: 'manufacturers' | 'importers' | 'pharmacies', key: Uint8Array) => {
      const leaf = partyLeaf(participantId(key));
      for (let attempt = 0; attempt < 30; attempt++) {
        const L = await live();
        const path = (L[which] as any).findPathForLeaf(leaf);
        if (path) return { root: L[which].root(), path, ledger: L };
        await new Promise((r) => setTimeout(r, 2000));
      }
      throw new Error(`${which} membership not found for caller (indexer never caught up)`);
    };

    // ---- deploy: seals the regulator (only its participant_id is on-chain) ----
    setActive({ callerSk: REGULATOR });
    log('Deploying contract (constructor seals the regulator)…');
    const deployResult = await deployContract(providers as any, {
      compiledContract,
      args: [],
      privateStateId: 'medpass',
      initialPrivateState: {},
    } as any);
    const contractAddress = String(deployResult.deployTxData.public.contractAddress);
    txids.deploy = String(deployResult.deployTxData.public.txId);
    txLine('deploy', deployResult);
    log(`  contract=${contractAddress}`);
    log();

    deployed = await findDeployedContract(providers as any, {
      compiledContract,
      contractAddress,
      privateStateId: 'medpass',
      initialPrivateState: {},
    } as any);

    const call = async (label: string, fn: () => Promise<any>) => {
      const r = await fn();
      txids[label] = String(r?.public?.txId ?? '');
      txLine(label, r);
      return r;
    };

    // ---- enroll parties (regulator only) ----
    rule();
    log('ENROLLMENT (regulator-only)');
    for (const [role, key, name] of [
      [PartyRole.MANUFACTURER, MANUFACTURER, 'register:manufacturer'],
      [PartyRole.IMPORTER, IMPORTER, 'register:importer'],
      [PartyRole.PHARMACY, PHARMACY_A, 'register:pharmacyA'],
      [PartyRole.PHARMACY, PHARMACY_B, 'register:pharmacyB'],
    ] as const) {
      setActive({ callerSk: REGULATOR });
      await call(name, () => deployed.callTx.register_party(role, participantId(key)));
    }

    // ---- manufacturer creates the batch (private Merkle membership proof) ----
    rule();
    log('MANUFACTURER creates a batch');
    const mfr = await membership('manufacturers', MANUFACTURER);
    setActive({ callerSk: MANUFACTURER, manufacturerPath: mfr.path });
    await call('create_batch', () =>
      deployed.callTx.create_batch(BATCH, mfr.root, UNIT_TREE.root, EXPIRY, METADATA),
    );

    // ---- importer records the import (identity stays private) ----
    log('IMPORTER records an authorized import (terms commitment only)');
    const imp = await membership('importers', IMPORTER);
    setActive({ callerSk: IMPORTER, importerPath: imp.path });
    await call('record_import', () => deployed.callTx.record_import(BATCH, imp.root, TERMS));

    // ---- pharmacist scans (read-only) then dispenses (consumes the unit) ----
    rule();
    log('PHARMACIST scans and dispenses');
    const phA = await membership('pharmacies', PHARMACY_A);
    setActive({ callerSk: PHARMACY_A, pharmacyPath: phA.path, unitCode: UNIT_CODES[0] });
    await call('verify (scan)', () => deployed.callTx.verify(BATCH, phA.root, UNIT_TREE.pathFor(0)));
    await call('dispense', () => deployed.callTx.dispense(BATCH, phA.root, UNIT_TREE.pathFor(0)));

    // ---- clone alarm: the same unit scanned again must fail ----
    log('CLONE ALARM: re-scanning the same unit must be rejected…');
    const phB = await membership('pharmacies', PHARMACY_B);
    setActive({ callerSk: PHARMACY_B, pharmacyPath: phB.path, unitCode: UNIT_CODES[0] });
    try {
      await deployed.callTx.dispense(BATCH, phB.root, UNIT_TREE.pathFor(0));
      log('  ✗ UNEXPECTED: clone was accepted');
    } catch (e) {
      log(`  ✓ rejected as expected: ${firstLine(e)}`);
    }

    // ---- recall: further scans must fail ----
    rule();
    log('RECALL: regulator recalls the batch; scans must fail');
    setActive({ callerSk: REGULATOR });
    await call('recall_batch', () => deployed.callTx.recall_batch(BATCH));
    const phA2 = await membership('pharmacies', PHARMACY_A);
    setActive({ callerSk: PHARMACY_A, pharmacyPath: phA2.path, unitCode: UNIT_CODES[1] });
    try {
      await deployed.callTx.verify(BATCH, phA2.root, UNIT_TREE.pathFor(1));
      log('  ✗ UNEXPECTED: recalled batch verified');
    } catch (e) {
      log(`  ✓ rejected as expected: ${firstLine(e)}`);
    }

    // ---- revocation: a struck-off pharmacy can no longer act ----
    rule();
    log('REVOCATION: regulator strikes off RuralHealth; its proofs stop working');
    setActive({ callerSk: REGULATOR });
    await call('revoke_party', () => deployed.callTx.revoke_party(participantId(PHARMACY_B)));
    const phB2 = await membership('pharmacies', PHARMACY_B);
    setActive({ callerSk: PHARMACY_B, pharmacyPath: phB2.path, unitCode: UNIT_CODES[2] });
    try {
      await deployed.callTx.verify(BATCH, phB2.root, UNIT_TREE.pathFor(2));
      log('  ✗ UNEXPECTED: revoked pharmacy verified');
    } catch (e) {
      log(`  ✓ rejected as expected: ${firstLine(e)}`);
    }

    // ---- read the on-chain ledger back through the indexer ----
    rule();
    log('ON-CHAIN LEDGER (read back through the indexer)');
    const L = await live();
    log(`  batch_count        ${L.batch_count.toString()}`);
    log(`  party_count        ${L.party_count.toString()}`);
    const rec = L.batches.lookup(BATCH);
    log(`  batch status       ${rec.status === 1 ? 'RECALLED' : 'ACTIVE'}`);
    log(`  batch expiry       ${rec.expiry.toString()}`);
    log(`  imported           ${L.imports.member(BATCH)}`);
    log(`  dispensed units    ${L.dispensed.size().toString()}`);
    log(`  revoked parties    ${L.revoked.size().toString()}`);

    // ---- persist the deployment record ----
    const dir = path.join(projectRoot, 'deployments');
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, `${network}.json`);
    fs.writeFileSync(file, JSON.stringify({
      contractName: 'medpass',
      network,
      contractAddress,
      endpoints: redactedConfig(config),
      txids,
      blockHeight: deployResult.deployTxData.public.blockHeight,
      batchId: toHex(BATCH),
      units: UNIT_CODES.map(toHex),
      ranAt: new Date().toISOString(),
    }, null, 2));

    log();
    rule();
    log(`Deployment record written to ${path.relative(projectRoot, file)}`);
    log();
  } finally {
    await walletCtx.wallet.stop();
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
